-- Execute com um schema Oracle que possua permissão para criar tabelas e identidade.
CREATE TABLE CP5_LIVRO (ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY, TITULO NVARCHAR2(150) NOT NULL, AUTOR NVARCHAR2(120) NOT NULL, ANOPUBLICACAO NUMBER(10) NOT NULL);
CREATE INDEX IDX_CP5_LIVRO_TITULO ON CP5_LIVRO(TITULO);
CREATE TABLE CP5_EMPRESTIMO (ID NUMBER GENERATED BY DEFAULT ON NULL AS IDENTITY PRIMARY KEY, LIVROID NUMBER(10) NOT NULL, LEITOR NVARCHAR2(120) NOT NULL, DATAEMPRESTIMO TIMESTAMP(7) NOT NULL, DATADEVOLUCAO TIMESTAMP(7), CONSTRAINT FK_CP5_EMPRESTIMO_LIVRO FOREIGN KEY(LIVROID) REFERENCES CP5_LIVRO(ID));
CREATE INDEX IDX_CP5_EMP_LIVRO ON CP5_EMPRESTIMO(LIVROID);
-- Os nomes das colunas refletem as propriedades das entidades EF Core (sem configuração adicional).
